import{_ as a,o,c as i,a6 as l}from"./chunks/framework.DL_pga9_.js";const m=JSON.parse('{"title":"Partial Move Semantics","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/partial_move_semantics.md","filePath":"design/archive/partial_move_semantics.md","lastUpdated":1780030916000}'),r={name:"design/archive/partial_move_semantics.md"};function t(c,e,d,s,n,p){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="partial-move-semantics" tabindex="-1">Partial Move Semantics <a class="header-anchor" href="#partial-move-semantics" aria-label="Permalink to “Partial Move Semantics”">​</a></h1><p>This document tracks Issue #38. The goal is to make <code>move obj.field</code> and <code>move tuple[0]</code> statically meaningful, with StorageCell moved sentinels kept as a runtime safety net rather than the long-term source of language semantics.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Partial moves depend on the value/reference/move model, <code>Drop</code>, and the StorageCell moved sentinel. They should remain earlier than generalized <code>= delete</code>, enhanced tuples, auto-derived traits, and fixed-size arrays because those features need stable initialization and destruction rules.</p><p>Array element partial move is still out of scope until constant generic parameters provide fixed-size arrays. Dynamic arrays should use explicit extraction APIs such as <code>take</code>, <code>replace</code>, or <code>swap_remove</code>; <code>move array[index]</code> is rejected today.</p><h2 id="place-model" tabindex="-1">Place Model <a class="header-anchor" href="#place-model" aria-label="Permalink to “Place Model”">​</a></h2><p>A tracked place is a lexical root plus structural components:</p><ul><li><code>value</code></li><li><code>obj.field</code></li><li><code>obj.inner.field</code></li><li><code>tuple[0]</code></li><li><code>tuple[0][1]</code></li><li><code>self.resource</code></li></ul><p>Object fields and tuple constant indexes are tracked recursively. Field access through a <code>ref&lt;T&gt;</code> receiver uses the same place key, so <code>move box.inner.left</code> can track a nested field even when <code>box</code> or <code>inner</code> is a reference.</p><p>Moving a whole binding marks the binding moved. Moving a field or tuple slot marks only that subplace moved. Reading the moved subplace is rejected, reading disjoint sibling places is allowed, and reading the containing whole place is rejected until all moved subplaces are restored.</p><p>Assignments restore initialization state:</p><ul><li><code>obj.field := value</code> clears the moved state for <code>obj.field</code>.</li><li><code>tuple[0] := value</code> clears the moved state for <code>tuple[0]</code>.</li><li><code>obj := value</code> clears all moved child state below <code>obj</code>.</li><li><code>obj.inner := value</code> clears all moved child state below <code>obj.inner</code>.</li></ul><h2 id="control-flow" tabindex="-1">Control Flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to “Control Flow”">​</a></h2><p>Partial-move state is propagated through compound scopes, branches, loops, and switches.</p><p>Branch and switch exits merge moved state conservatively: if a place may be moved on any path, it is treated as moved after the control-flow construct. If every path restores the same moved place, the restored state is visible after the branch.</p><p>Loop bodies propagate moved state to the loop exit. This is intentionally conservative because the current checker does not prove loop iteration counts or path reachability.</p><p>Lexical scope filtering removes places and direct borrow aliases whose roots leave scope.</p><h2 id="direct-borrow-tracking" tabindex="-1">Direct Borrow Tracking <a class="header-anchor" href="#direct-borrow-tracking" aria-label="Permalink to “Direct Borrow Tracking”">​</a></h2><p>The checker tracks direct lexical aliases created by <code>ref place</code> and <code>&amp;place</code>.</p><p>While a direct alias is live:</p><ul><li>moving the borrowed place is rejected</li><li>assigning the borrowed place is rejected</li><li>moving through the alias, such as <code>move *borrowed</code>, is rejected</li><li>moving or assigning disjoint sibling places is allowed</li><li>leaving the alias scope releases the borrow</li></ul><p>This is not a full lifetime or arbitrary alias graph. It is a direct-place borrow check for the current <code>ref</code> surface and prevents the main unsound cases introduced by partial move.</p><h2 id="method-effects" tabindex="-1">Method Effects <a class="header-anchor" href="#method-effects" aria-label="Permalink to “Method Effects”">​</a></h2><p>Receiver methods carry inferred structural effects relative to the receiver parameter, conventionally <code>self</code>.</p><p>The type checker records ordered receiver effects:</p><ul><li>reads: <code>self.field</code>, <code>self.tuple[0]</code></li><li>writes: <code>self.field := value</code></li><li>moves: <code>move self.field</code></li><li>unknown effects: taking a ref to receiver state or calling through receiver state when effects cannot be resolved</li></ul><p>Calling a method on a partially moved receiver is allowed only when the ordered effects do not read or move a moved place. Writes restore the written place, so a method that only assigns <code>self.left</code> can reinitialize <code>box.left</code> after <code>move box.left</code>. Whole-receiver or unknown-effect methods remain conservative and require the receiver to be fully initialized.</p><p>Method moves update the caller&#39;s place state. This is required for <code>Drop::drop(self: ref&lt;Self&gt;)</code> implementations that consume resource fields with <code>move self.ptr</code>.</p><h2 id="drop-rules" tabindex="-1">Drop Rules <a class="header-anchor" href="#drop-rules" aria-label="Permalink to “Drop Rules”">​</a></h2><p>Drop is field-aware and deterministic across STUPID and ORGASM:</p><ul><li>initialized fields are dropped normally</li><li>moved-out fields are skipped</li><li>remaining initialized child fields are dropped after a custom/native <code>Drop</code> handler</li><li>custom <code>Drop::drop(self: ref&lt;Self&gt;)</code> may move resource fields</li><li>a field moved inside <code>Drop::drop</code> is not double-dropped by recursive child cleanup</li></ul><p>The runtime still checks moved sentinels before dropping a cell. This is a safety net and debugging assertion for STUPID/ORGASM. A future native backend should rely on static place checking and should not need a dynamic moved check for well-typed code.</p><h2 id="acceptance-coverage" tabindex="-1">Acceptance Coverage <a class="header-anchor" href="#acceptance-coverage" aria-label="Permalink to “Acceptance Coverage”">​</a></h2><p>Current tests cover:</p><ul><li><code>move obj.field</code> allows reading sibling fields.</li><li>reading the moved field fails.</li><li>reading the whole object after a partial move fails.</li><li>method calls on partially moved receivers use inferred read/write/move effects.</li><li>method writes can restore moved receiver fields.</li><li>nested field moves and whole-place overwrites clear child state.</li><li><code>move tuple[0]</code> and nested tuple constant-index moves.</li><li>branch, switch, loop, and scope moved-state propagation.</li><li>direct <code>ref</code> aliases reject conflicting move/assignment and release at lexical scope exit.</li><li><code>move array[0]</code> is rejected.</li><li>STUPID and ORGASM both run partial-move and Drop regression examples.</li></ul>',35)])])}const f=a(r,[["render",t]]);export{m as __pageData,f as default};
